    protected TAMRebateId copyRebateTable()
    {
        RefRecId    rebateLineAttributeRule;

        rebateLineAttributeRule = TAMRebateTable::find(this.rebateId).PricingRuleLine;

        TAMRebateId copiedRebateId = next copyRebateTable();

        TAMRebateCopy::METCopyRebateTableAttributeExcludeForPayment(copiedRebateId, rebateLineAttributeRule);

        return copiedRebateId;
    }

static TAMRebateTable METCopyRebateTableAttributeExcludeForPayment(TAMRebateId _copiedRebateId, RefRecId _rebateLineAttributeRule)
{        
    RecordInsertList                    excludeProductsRecordInsertList;
    METExcludeForPaymentProducts        rebateLineProductsCopy, rebateLineProducts;
    
    TAMRebateTable copiedRebateTable = TAMRebateTable::find(_copiedRebateId, true);
    if (copiedRebateTable.ModuleInventCustVend == ModuleInventCustVend::Cust)
    {
        excludeProductsRecordInsertList = new RecordInsertList(tableNum(METExcludeForPaymentProducts));
        while select ItemId from rebateLineProducts where rebateLineProducts.RuleId == _rebateLineAttributeRule
        {
            rebateLineProductsCopy.ItemId = rebateLineProducts.ItemId;
            rebateLineProductsCopy.RuleId = copiedRebateTable.PricingRuleLine;
            if(rebateLineProductsCopy.validateWrite())
            {
                excludeProductsRecordInsertList.add(rebateLineProductsCopy);
            }
        }        
        excludeProductsRecordInsertList.insertDatabase();
    }
    
    return copiedRebateTable;
}
